import{_ as t,o as e,c as i,a3 as s}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"快速上手","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"快速上手 | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/catter/guide/quick-start"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/guide/quick-start"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/guide/quick-start"}]]},"headers":[],"relativePath":"zh/catter/guide/quick-start.md","filePath":"zh/catter/guide/quick-start.md","lastUpdated":1792936908000}'),h={name:"zh/catter/guide/quick-start.md"};function l(d,a,n,r,o,c){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>使用任意构建系统（Make、Ninja、CMake、Meson 等）的 C++ 项目</li></ul><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>Catter 通过 GitHub Releases 分发预编译包。前往 <a href="https://github.com/clice-io/catter/releases" target="_blank" rel="noreferrer">GitHub Releases</a> 页面，下载对应平台的压缩包，解压后将 <code>catter</code> 可执行文件所在目录加入 <code>PATH</code> 即可。</p><p>预编译包当前支持的平台：</p><table tabindex="0"><thead><tr><th>平台</th><th>架构</th></tr></thead><tbody><tr><td>Windows</td><td>x64、arm64</td></tr><tr><td>Linux</td><td>x64</td></tr><tr><td>macOS</td><td>arm64</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Catter 目前仍在积极开发中，请以 Releases 页面为准获取最新版本。如果您的平台没有预编译包，可以参阅<a href="./../dev/build">从源码构建</a>自行编译。</p></div><h2 id="生成编译数据库" tabindex="-1">生成编译数据库 <a class="header-anchor" href="#生成编译数据库" aria-label="Permalink to &quot;生成编译数据库&quot;">​</a></h2><p>通过 catter 运行你的构建命令，即可捕获所有编译器调用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile-commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><p>这会在当前目录生成 <code>compile_commands.json</code> 文件，可直接用于任何语言服务器或静态分析工具。</p><h2 id="命令格式" tabindex="-1">命令格式 <a class="header-anchor" href="#命令格式" aria-label="Permalink to &quot;命令格式&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>catter &lt;command&gt; [options] -- &lt;build-command&gt;</span></span></code></pre></div><p>以上面的 CDB 示例为例：</p><table tabindex="0"><thead><tr><th>部分</th><th>含义</th></tr></thead><tbody><tr><td><code>compile-commands</code></td><td>命令：生成 CDB</td></tr><tr><td><code>-o compile_commands.json</code></td><td>命令的选项：输出文件路径</td></tr><tr><td><code>--</code></td><td>命令的参数与构建命令之间的分隔符</td></tr><tr><td><code>make</code></td><td>实际要拦截的构建命令</td></tr></tbody></table><p><code>catter --help</code> 列出所有命令，<code>catter &lt;command&gt; --help</code> 显示某个命令的选项。</p><h2 id="更多示例" tabindex="-1">更多示例 <a class="header-anchor" href="#更多示例" aria-label="Permalink to &quot;更多示例&quot;">​</a></h2><h3 id="命令树可视化" tabindex="-1">命令树可视化 <a class="header-anchor" href="#命令树可视化" aria-label="Permalink to &quot;命令树可视化&quot;">​</a></h3><p>将捕获的构建命令 DAG 以 ASCII 树形式展示：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tree</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make</span></span></code></pre></div><h3 id="配合-cmake-使用" tabindex="-1">配合 CMake 使用 <a class="header-anchor" href="#配合-cmake-使用" aria-label="Permalink to &quot;配合 CMake 使用&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile-commands</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile_commands.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><h3 id="你自己的-handler" tabindex="-1">你自己的 handler <a class="header-anchor" href="#你自己的-handler" aria-label="Permalink to &quot;你自己的 handler&quot;">​</a></h3><p>把命令交给你自己编写的程序，即 <a href="./../scripting/handlers">handler</a>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">catter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --handler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;python my_handler.py&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div>',26)])])}const g=t(h,[["render",l]]);export{k as __pageData,g as default};
